async function commitConclusion(deps:PipelineDeps,matchId:string,runId:string):Promise<StageOutcome>{const run=await deps.getLatestRun(matchId);if(run?.independent_decision_committed_at)return{status:"COMPLETE",done:1,total:1};const match=await deps.getMatch(matchId);if(!match)throw new Error("match disappeared");const metrics=await deps.list("metric_results",runId),evidence=digestFrom(match,metrics),conclusion=await provisionalConclusion(deps,matchId,runId,evidence),families=new Set(metrics.filter(m=>m["matrix_derived"]!==true&&m["status"]==="COMPLETE"&&m["evidence_family"]).map(m=>String(m["evidence_family"])));if(!conclusion.winner){await deps.updateRun(runId,{independent_decision_committed_at:deps.now().toISOString(),effective_evidence_count:families.size,raw_signal_count:metrics.filter(m=>m["status"]==="COMPLETE").length});return{status:"COMPLETE",done:1,total:1,detail:{winner:null,families:families.size,insufficient_reason:conclusion.insufficient_reason??"Independent evidence was insufficient to commit a conclusion."}};}await deps.updateRun(runId,{independent_winner:conclusion.winner,independent_low:conclusion.low,independent_high:conclusion.high,independent_decision_committed_at:deps.now().toISOString(),effective_evidence_count:families.size,raw_signal_count:metrics.filter(m=>m["status"]==="COMPLETE").length});return{status:"COMPLETE",done:1,total:1,detail:{winner:conclusion.winner,families:families.size,rationale:conclusion.rationale?.slice(0,500)??null}};}
async function revealMatrix(deps:PipelineDeps,matchId:string,runId:string):Promise<StageOutcome>{const run=await deps.getLatestRun(matchId);if(!run?.independent_decision_committed_at)return{status:"BLOCKED",done:0,total:1,errorCode:"FIREWALL",message:"Matrix stays sealed until the independent conclusion is committed."};const fields=await deps.getParsedFields(matchId),wpRaw=fields["matrix_wp"],wp=wpRaw?Number(String(wpRaw).replace(/[^\d.]/g,"")):null;await deps.updateRun(runId,{matrix_revealed_at:deps.now().toISOString()});return{status:"COMPLETE",done:1,total:1,detail:{matrix_predicted_winner:fields["matrix_predicted_winner"]??null,matrix_wp:wp,agrees_with_independent:fields["matrix_predicted_winner"]&&run.independent_winner?fields["matrix_predicted_winner"].toLowerCase().includes(run.independent_winner.split(" ").slice(-1)[0]!.toLowerCase()):null}};}
async function applyCalibration(deps:PipelineDeps,matchId:string,runId:string):Promise<StageOutcome>{const{version,buckets}=await deps.getCalibration();if(!version||!buckets.length)return{status:"FAILED",done:0,total:1,errorCode:"NO_ACTIVE_CALIBRATION",message:"No active calibration version with buckets is stored."};const run=await deps.getLatestRun(matchId),fields=await deps.getParsedFields(matchId),wpRaw=fields["matrix_wp"],wp=wpRaw?Number(String(wpRaw).replace(/[^\d.]/g,"")):null,bucket=bucketFor(wp,buckets),rate=bucket?winRate(bucket.wins,bucket.graded):null,centre=rate??(((run?.independent_low??0)+(run?.independent_high??0))/2||null);await deps.updateRun(runId,{calibration_version_id:version.id,calibrated_low:centre===null?null:Math.max(0,Math.round(centre-5)),calibrated_high:centre===null?null:Math.min(100,Math.round(centre+5))});return{status:"COMPLETE",done:1,total:1,detail:{calibration_version:version.label,version_number:version.version_number,bucket:bucket?.bucket_code??null,verified_win_rate:rate}};}

async function finalGate(deps:PipelineDeps,matchId:string,runId:string):Promise<StageOutcome>{const report=await buildReport(deps,matchId,runId);await deps.saveCoverage(runId,[{player_side:"P1",...report.coverage.p1},{player_side:"P2",...report.coverage.p2}]);await deps.saveCoverageRates(runId,[{player_side:"P1",metric_family:"ALL",direct_count:report.coverage.p1.direct,reconstructed_count:report.coverage.p1.reconstructed,partial_count:report.coverage.p1.partial,unavailable_count:report.coverage.p1.unavailable,excluded_count:report.coverage.p1.excluded,total_count:report.coverage.p1.total,usable_percent:report.coverage.p1.usablePercent},{player_side:"P2",metric_family:"ALL",direct_count:report.coverage.p2.direct,reconstructed_count:report.coverage.p2.reconstructed,partial_count:report.coverage.p2.partial,unavailable_count:report.coverage.p2.unavailable,excluded_count:report.coverage.p2.excluded,total_count:report.coverage.p2.total,usable_percent:report.coverage.p2.usablePercent}]);const run=await deps.getLatestRun(matchId),existing=await deps.getDecisionId(runId);await deps.saveDecision(runId,existing,{final_audit_color:report.color,final_recommendation:report.action,completion_percent:report.completionPercent,independent_winner:run?.independent_winner??null,independent_range:run?.independent_low!==null&&run?.independent_high!==null?`${run?.independent_low}-${run?.independent_high}`:null,calibrated_range:run?.calibrated_low!==null&&run?.calibrated_high!==null?`${run?.calibrated_low}-${run?.calibrated_high}`:null,green_locked:report.greenLocked,green_lock_reasons:report.greenLockReasons,matrix_firewall_valid:report.matrixFirewallValid});return{status:"COMPLETE",done:1,total:1,detail:{color:report.color,action:report.action,completion_percent:report.completionPercent,evidence_coverage:report.coverage.usablePercent}};}
async function buildReport(deps:PipelineDeps,matchId:string,runId:string):Promise<GateReport>{const match=await deps.getMatch(matchId),run=await deps.getLatestRun(matchId);if(!match||!run)throw new Error("match/run missing while building report");const[metrics,verification,disagreement,underdog,stress,conflicts,reconstructions]=await Promise.all([deps.list("metric_results",runId),deps.list("verification_results",runId),deps.list("disagreement_results",runId),deps.list("underdog_results",runId),deps.list("stress_results",runId),deps.getConflicts(runId),deps.getReconstructions(runId)]);const fields=await deps.getParsedFields(matchId),wpRaw=fields["matrix_wp"],matrixWp=wpRaw?Number(String(wpRaw).replace(/[^\d.]/g,"")):null;return evaluate({match,run,metrics:metrics as never,verification:verification as never,disagreement:disagreement as never,underdog:underdog as never,stress:stress as never,reconstructions,conflicts,matrixWp});}
